class Solution {
    public int findTargetSumWays(int[] nums,int target){
        Map<Integer,Integer> ways=new HashMap<>();
        ways.put(0,1);
        for(int value:nums){
            Map<Integer,Integer> next=new HashMap<>();
            for(Map.Entry<Integer,Integer> entry:ways.entrySet()){
                next.merge(entry.getKey()+value,entry.getValue(),Integer::sum);
                next.merge(entry.getKey()-value,entry.getValue(),Integer::sum);
            }
            ways=next;
        }
        return ways.getOrDefault(target,0);
    }
}

code.kotlin:
class Solution {
    fun findTargetSumWays(nums:IntArray,target:Int):Int{
        var ways=hashMapOf(0 to 1);
        for(value in nums){
            val next=hashMapOf<Int,Int>();
            for((sum,count) in ways){
                next[sum+value]=(next[sum+value]?:0)+count;
                next[sum-value]=(next[sum-value]?:0)+count
            };
            ways=next
        };
        return ways[target]?:0
    }
}

code.cpp:
class Solution {
    public: int findTargetSumWays(vector<int>& nums,int target){
        unordered_map<int,int> ways{
            {
                0,1
            }
        };
        for(int value:nums){
            unordered_map<int,int> next;
            for(auto [sum,count]:ways){
                next[sum+value]+=count;
                next[sum-value]+=count;
            }
            ways=move(next);
        }
        return ways[target];
    }
};
